function singleNumber(nums) {
  const counts = new Map();
  for (const value of nums) counts.set(value, (counts.get(value) || 0) + 1);
  const out = [];
  for (const [value, n] of counts) if (n === 1) out.push(value);
  out.sort((a, b) => a - b);
  return out;
}

