function singleNumber(nums) {
  let diff = 0;
  for (const value of nums) diff ^= value;
  const bit = diff & -diff;
  let withBit = 0;
  let withoutBit = 0;
  for (const value of nums) {
    if (value & bit) withBit ^= value;
    else withoutBit ^= value;
  }
  return withBit < withoutBit ? [withBit, withoutBit] : [withoutBit, withBit];
}

