def single_number(nums):
    diff = 0
    for value in nums:
        diff ^= value
    bit = diff & -diff
    with_bit = 0
    without_bit = 0
    for value in nums:
        if value & bit:
            with_bit ^= value
        else:
            without_bit ^= value
    return sorted([with_bit, without_bit])

